answer.sqlserver:
SELECT TOP 10 Name, ListPrice
FROM SalesLT.Product
ORDER BY ListPrice DESC, Name;

answer.default:
SELECT ProductID, Name, Color, ListPrice
FROM SalesLT.Product
ORDER BY Color, ListPrice DESC, ProductID;

SELECT Color, COUNT(*) AS ProductCount
FROM SalesLT.Product
GROUP BY Color;

SELECT ProductID, SUM(OrderQty) AS TotalQty
FROM SalesLT.SalesOrderDetail
GROUP BY ProductID;

SELECT p.Name AS Product, c.Name AS Category
FROM SalesLT.Product p
JOIN SalesLT.ProductCategory c ON c.ProductCategoryID = p.ProductCategoryID;

SELECT c.Name AS Category, parent.Name AS ParentCategory
FROM SalesLT.ProductCategory c
JOIN SalesLT.ProductCategory parent ON parent.ProductCategoryID = c.ParentProductCategoryID;

SELECT ProductID, Name, ListPrice
FROM SalesLT.Product
WHERE ListPrice > (SELECT AVG(ListPrice) FROM SalesLT.Product);

SELECT ProductID, Name
FROM SalesLT.Product
WHERE ProductID IN (SELECT ProductID FROM SalesLT.SalesOrderDetail);

SELECT p.ProductID, p.Name
FROM SalesLT.Product p
WHERE NOT EXISTS (SELECT 1 FROM SalesLT.SalesOrderDetail d WHERE d.ProductID = p.ProductID);

SELECT p.ProductCategoryID, p.Name, p.ListPrice
FROM SalesLT.Product p
WHERE p.ListPrice = (
  SELECT MAX(x.ListPrice) FROM SalesLT.Product x
  WHERE x.ProductCategoryID = p.ProductCategoryID
);

SELECT SalesOrderID, TotalDue,
       ROUND(TotalDue * 100 / (SELECT SUM(TotalDue) FROM SalesLT.SalesOrderHeader), 2) AS PctOfTotal
FROM SalesLT.SalesOrderHeader;

SELECT AVG(LineCount * 1.0) AS AvgLines
FROM (
  SELECT SalesOrderID, COUNT(*) AS LineCount
  FROM SalesLT.SalesOrderDetail
  GROUP BY SalesOrderID
) t;

SELECT ProductCategoryID, Name, ListPrice,
       ROW_NUMBER() OVER (PARTITION BY ProductCategoryID ORDER BY ListPrice DESC, ProductID) AS RowNum
FROM SalesLT.Product;

SELECT ProductID, Name, ListPrice,
       AVG(ListPrice) OVER (PARTITION BY ProductCategoryID) AS CategoryAvg
FROM SalesLT.Product;

