SELECT YEAR(SellStartDate) AS StartYear, COUNT(*) AS Products
FROM SalesLT.Product
GROUP BY YEAR(SellStartDate);

answer.postgres:
SELECT EXTRACT(YEAR FROM SellStartDate) AS StartYear, COUNT(*) AS Products
FROM SalesLT.Product
GROUP BY EXTRACT(YEAR FROM SellStartDate);

answer.sqlserver:
SELECT Name, DATEDIFF(day, SellStartDate, SellEndDate) AS DaysOnSale
FROM SalesLT.Product
WHERE SellEndDate IS NOT NULL;

answer.mysql:
SELECT Name, DATEDIFF(SellEndDate, SellStartDate) AS DaysOnSale
FROM SalesLT.Product
WHERE SellEndDate IS NOT NULL;

answer.postgres:
SELECT Name, CAST(SellEndDate AS DATE) - CAST(SellStartDate AS DATE) AS DaysOnSale
FROM SalesLT.Product
WHERE SellEndDate IS NOT NULL;

